import "std:text" as text
try { text.find(5, "a") } catch e { print(e) }
try { text.find("a", 5) } catch e { print(e) }
try { text.starts_with([], "a") } catch e { print(e) }
try { text.is_number(5) } catch e { print(e) }
try { text.basename(true) } catch e { print(e) }
try { text.find_from("a", "a", 1.5) } catch e { print(e) }
try { text.find_from("a", "a", "1") } catch e { print(e) }
